#!/usr/bin/env node

import {
  developmentIssuer,
  developmentResource,
} from "./lib/development-deployment.mjs";
import { developmentTopologyDatabases } from "./lib/development-topology-deployment.mjs";
import { isMain } from "./lib/production-deployment.mjs";
import { testLocalOAuth } from "./test-local-oauth.mjs";

export function developmentOAuthConfiguration(options = {}) {
  const workspaceSlugs =
    options.workspaceSlugs ??
    (process.env.SKILLPLANE_OAUTH_WORKSPACE_SLUGS ?? "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean);
  const databases = options.databases ?? developmentTopologyDatabases();
  return {
    databaseUrl: databases.control.url,
    issuer: developmentIssuer,
    resource: developmentResource,
    workspaceSlugs,
    ...(process.env.SKILLPLANE_OAUTH_NO_BROWSER === "1"
      ? { openBrowser: () => undefined }
      : {}),
  };
}

export async function testDevelopmentOAuth(options = {}) {
  const verify = options.verify ?? testLocalOAuth;
  return verify(developmentOAuthConfiguration(options));
}

if (isMain(import.meta.url)) {
  process.stdout.write(`${JSON.stringify(await testDevelopmentOAuth(), null, 2)}\n`);
}
import {
  developmentSecrets,
  developmentPostHogProjectToken,
} from "./development-deployment.mjs";
import {
  requireEnvironment,
  requireSecretEnvironment,
} from "./production-deployment.mjs";
import { validateDatafnTicketKeys } from "./datafn-ticket-keys.mjs";

export function topologySecrets(output) {
  if (output.kind === "projection" || output.kind === "datafn") return null;
  const development = developmentSecrets();
  const shared = {
    OAUTH_TOKEN_PEPPER: development.OAUTH_TOKEN_PEPPER,
    WORKSPACE_ROUTING_KEYS: JSON.stringify({
      current: requireSecretEnvironment("SKILLPLANE_DEV_WORKSPACE_ROUTING_SECRET"),
    }),
  };
  const direct = output.config?.vars?.DATAFN_DIRECT_ENABLED === "true";
  const ticketKeys = direct
    ? validateDatafnTicketKeys({
        activeKeyId: requireEnvironment("DATAFN_ROUTE_ACTIVE_KEY_ID"),
        privateKey: requireSecretEnvironment("DATAFN_ROUTE_PRIVATE_KEY_PEM"),
        publicKeysJson: requireEnvironment("DATAFN_ROUTE_PUBLIC_KEYS"),
      })
    : null;
  if (output.id === "gateway:app") {
    return {
      AUTHFN_SECRET: development.AUTHFN_SECRET,
      TURNSTILE_SECRET_KEY: development.TURNSTILE_SECRET_KEY,
      ...shared,
      ...(direct
        ? {
            DATAFN_ROUTE_ACTIVE_KEY_ID: ticketKeys.activeKeyId,
            DATAFN_ROUTE_PRIVATE_KEY_PEM: ticketKeys.privateKey,
            AUTHFN_PLACEMENT_SUBJECT_SECRET: requireSecretEnvironment(
              "AUTHFN_PLACEMENT_SUBJECT_SECRET",
            ),
          }
        : {}),
    };
  }
  if (output.kind === "mcp") {
    return {
      ...shared,
      POSTHOG_PROJECT_TOKEN: developmentPostHogProjectToken(),
    };
  }
  return {
    ...shared,
    ...(direct ? { DATAFN_ROUTE_PUBLIC_KEYS: ticketKeys.publicKeysJson } : {}),
  };
}
#!/usr/bin/env node

import { spawnSync } from "node:child_process";

const workspaceAliases = new Map([
  ["app", "@skillplane/app"],
  ["mcp", "@skillplane/mcp"],
]);
const input = process.argv.slice(2);
const argumentsForTurbo = [];

for (let index = 0; index < input.length; index += 1) {
  const argument = input[index];
  if (argument === "--filter") {
    const value = input[index + 1];
    if (!value) {
      process.stderr.write("--filter requires a workspace name\n");
      process.exit(2);
    }
    argumentsForTurbo.push("--filter", workspaceAliases.get(value) ?? value);
    index += 1;
  } else if (argument?.startsWith("--filter=")) {
    const value = argument.slice("--filter=".length);
    argumentsForTurbo.push(`--filter=${workspaceAliases.get(value) ?? value}`);
  } else if (argument) {
    argumentsForTurbo.push(argument);
  }
}

const result = spawnSync(
  "pnpm",
  ["exec", "turbo", "run", "build", ...argumentsForTurbo],
  {
    stdio: "inherit",
  },
);
process.exit(result.status ?? 1);

