  readonly credential: {
    readonly kind: "oauth_access_token" | "service_principal";
    readonly id: string;
    readonly clientId?: string;
  };
  readonly caller: MutationCallerDeclaration;
}

export interface MutationAuditEvent {
  readonly eventType: string;
  readonly action:
    "skills:write" | "skills:amend" | "skills:publish" | "contexts:write";
  readonly requestId: string;
  readonly resourceType:
    | "skill"
    | "skill_version"
    | "amendment_review"
    | "context"
    | "context_knowledge_revision"
    | "context_note_revision";
  readonly resourceId: string;
  readonly skillId?: string;
  readonly versionId?: string;
  readonly contextId?: string;
  readonly metadata: Readonly<Record<string, unknown>>;
}

export interface PrincipalAuditEvent {
  readonly auditContext?: MutationAuditContext;
