async function publicVersionsEtag(
  versions: readonly ReturnType<typeof publicPublishedSkillVersion>[],
): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(JSON.stringify(versions)),
  );
  const hex = [...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
  return `"versions-${hex}"`;
}

function parseLimit(value: string | undefined): number | undefined {
  if (value === undefined) return undefined;
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < 1 || parsed > 100) {
    throw new DomainError(
      "VALIDATION_FAILED",
      "limit must be an integer between 1 and 100",
      400,
      { field: "limit" },
    );
  }
  return parsed;
}

function parseVisibilityFilter(context: {
  req: {
    queries(name: string): string[] | undefined;
    query(name: string): string | undefined;
  };
}): readonly SkillVisibility[] {
