    `SELECT table_name
         FROM information_schema.tables AS candidate
        WHERE table_schema = 'public'
          AND table_type = 'BASE TABLE'
          AND (
            left(table_name, 9) = '__datafn_'
            OR EXISTS (
              SELECT 1
                FROM information_schema.columns AS column_definition
