        }
        return value;
      }),
    ),
  ].sort();
  const archive = options.archive ?? "active";
  if (!(SKILL_ARCHIVE_FILTERS as readonly string[]).includes(archive)) {
    throw new DomainError(
      "VALIDATION_FAILED",
      "Skill state must be active, archived, or all",
      400,
      { field: "state" },
