import type { AuthFnSession } from "authfn";
import {
  DomainError,
  WorkspaceAccessError,
  isWorkspaceRole,
  type UserPrincipal,
  type WorkspaceRole,
} from "@skillplane/domain";
import type { Pool, PoolClient } from "pg";

interface MembershipRow {
  readonly id: string;
  readonly role: string;
  readonly user_id: string;
  readonly workspace_id: string;
  readonly email: string | null;
  readonly display_name: string | null;
}

function id(prefix: string): string {
  return `${prefix}:${crypto.randomUUID()}`;
}

async function stablePersonalSlug(userId: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(userId),
  );
  const suffix = [...new Uint8Array(digest)]
    .slice(0, 10)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
  return `personal-${suffix}`;
}

export async function ensurePersonalWorkspace(
  pool: Pool,
  session: AuthFnSession,
  homeRegionId: string | (() => string) = "legacy",
): Promise<string> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [
      session.actorId,
    ]);
    const existing = await client.query<{ id: string }>(
      `SELECT id FROM workspaces
        WHERE kind = 'personal' AND personal_owner_user_id = $1
        LIMIT 1`,
      [session.actorId],
    );
    let workspaceId = existing.rows[0]?.id;
    if (!workspaceId) {
      const resolvedHomeRegionId =
