  app.post(base,async c=>{const principal=await workspaceUser(c),s=c.get("services")!,body=await readJsonObject(c);const group=await new SkillGroupService(s.database.pool,s.controlDatabase.pool).create({principal,name:body.name,description:body.description,idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});return c.json(success(c,{group}),201);});
