  app.patch(`${base}/:groupId`,async c=>{const principal=await workspaceUser(c),s=c.get("services")!,body=await readJsonObject(c);if(typeof body.archived!=="boolean"||typeof body.expectedRevision!=="number")throw new DomainError("VALIDATION_FAILED","Revision and archived state are required",400);const group=await new SkillGroupService(s.database.pool,s.controlDatabase.pool).update({principal,groupId:c.req.param("groupId"),expectedRevision:body.expectedRevision,name:body.name,description:body.description,archived:body.archived,requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});return c.json(success(c,{group}));});
  app.get(`${base}/:groupId/members`,async c=>{const principal=await workspaceUser(c),s=c.get("services")!;const data=await new SkillGroupService(s.database.pool,s.controlDatabase.pool).members(principal,c.req.param("groupId"),groupPage(c.req.query("limit")??50,c.req.query("cursor")??null));c.header("Cache-Control","private, no-store");return c.json(success(c,data));});
  for(const kind of ["skills","members"] as const)for(const method of ["put","delete"] as const){app[method](`${base}/:groupId/${kind}/:targetId`,async c=>{const principal=await workspaceUser(c),s=c.get("services")!;const data=await new SkillGroupService(s.database.pool,s.controlDatabase.pool).association({principal,groupId:c.req.param("groupId"),kind:kind==="skills"?"skill":"member",targetId:c.req.param("targetId"),add:method==="put",requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});return c.json(success(c,data));});}
}
