      error = e instanceof Error ? e.message : "The change failed";
    } finally {
      busy = false;
    }
  }
  async function save(archived = Boolean(selected?.archivedAt)) {
    if (!workspace) return;
    const r = await groupRequest<{ group: Group }>(
      workspace.id,
