import { api, runtimeBindings } from "$lib/server/api.js";
import { withBrowserSecurityHeaders } from "$lib/server/security-headers.js";
import type { Handle } from "@sveltejs/kit";

export const handle: Handle = async ({ event, resolve }) => {
  const pathname = event.url.pathname;
  if (
    pathname.startsWith("/auth/") ||
    pathname.startsWith("/datafn/") ||
    pathname.startsWith("/.well-known/")
  ) {
    return api.fetch(event.request, runtimeBindings(event.platform));
  }

  return withBrowserSecurityHeaders(await resolve(event));
};
import { redirect } from "@sveltejs/kit";
import { loadBrowserSession } from "$lib/server/browser-session.js";
import type { LayoutServerLoad } from "./$types";

export const load: LayoutServerLoad = async ({ platform, request, url }) => {
  const session = await loadBrowserSession({ platform, request, url });
  if (!session) {
    const returnTo = `${url.pathname}${url.search}`;
    redirect(303, `/sign-in?next=${encodeURIComponent(returnTo)}`);
  }

  return { session };
};
<script lang="ts">
  import { goto } from "$app/navigation";
  import { resolve } from "$app/paths";
  import { page } from "$app/state";
  import {
    CommandMenu,
    ErrorState,
    Skeleton,
    applyAppearance,
    isTheme,
    type CommandItem,
    type Theme,
  } from "@skillplane/ui";
  import { RobotIcon, SquaresFourIcon, UsersThreeIcon } from "phosphor-svelte";
  import { onMount, type Snippet } from "svelte";
  import { signOut, type BrowserSession } from "$lib/auth/client.js";
  import { identifyPostHog, resetPostHog } from "$lib/analytics/posthog.client.js";
  import type { WorkspaceStore } from "$lib/workspaces/store.svelte.js";
  import Sidebar from "./Sidebar.svelte";
  import Topbar from "./Topbar.svelte";

  let {
    session,
    workspaces,
    children,
  }: {
    session: BrowserSession;
    workspaces: WorkspaceStore;
    children: Snippet;
  } = $props();

  let navigationOpen = $state(false);
  let commandsOpen = $state(false);
  let theme = $state<Theme>("dark");
  let initialized = $state(false);

  const commands: readonly CommandItem[] = [
    {
      id: "workspaces",
      label: "Open workspaces",
      group: "Navigate",
      keywords: ["organization", "workspace"],
      icon: SquaresFourIcon,
      run: () => goto(resolve("/workspaces")),
    },
    {
      id: "members",
      label: "Manage members",
      group: "Navigate",
      keywords: ["invitations", "roles"],
      icon: UsersThreeIcon,
      run: () => goto(resolve("/settings/members")),
    },
    {
      id: "agents",
      label: "Manage agent credentials",
      group: "Navigate",
      keywords: ["service principal", "tokens"],
      icon: RobotIcon,
      run: () => goto(resolve("/settings/agents")),
    },
  ];

  async function leaveSession() {
    await signOut();
    resetPostHog();
    await goto(resolve("/sign-in"));
  }

  function toggleTheme() {
    theme = theme === "dark" ? "light" : "dark";
    applyAppearance(theme);
  }

  async function loadWorkspaces() {
    await workspaces.load();
    initialized = true;
  }

  onMount(() => {
    identifyPostHog(session.actorId, {
      ...(session.subject.email ? { email: session.subject.email } : {}),
    });

    const storedTheme = localStorage.getItem("skillplane.theme");
    theme = isTheme(storedTheme) ? storedTheme : "dark";
    applyAppearance(theme);
    void loadWorkspaces();
  });

  $effect(() => {
    if (!initialized || typeof page.params.workspaceSlug !== "string") return;
    const routed = workspaces.workspaces.find(
      (workspace) => workspace.slug === page.params.workspaceSlug,
    );
    if (routed && workspaces.activeId !== routed.id) {
      workspaces.select(routed.id);
    }
  });
</script>

{#if !initialized}
  <main class="boot" aria-label="Opening Skillplane" aria-busy="true">
    <div>
      <Skeleton width="2.25rem" height="2.25rem" radius="var(--sp-radius-lg)" />
      <Skeleton width="12rem" height="1rem" />
      <Skeleton width="18rem" height="0.75rem" />
    </div>
  </main>
{:else if workspaces.error}
  <main class="boot error">
    <ErrorState
      title="Skillplane did not open"
      description={workspaces.error}
      retry={() => void loadWorkspaces()}
    />
  </main>
{:else}
  <div class="shell">
    <Sidebar
      open={navigationOpen}
      pathname={page.url.pathname}
      store={workspaces}
      onClose={() => (navigationOpen = false)}
    />
    {#if navigationOpen}
      <button
        class="scrim"
        type="button"
        aria-label="Close navigation"
