import { pgTable,text,integer,timestamp,jsonb,uniqueIndex,foreignKey,primaryKey,index,check } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { skills,skillVersions } from "./domain.js";
const utc=(name:string)=>timestamp(name,{withTimezone:true,mode:"date"});
export const skillSources=pgTable("skill_sources",{
 id:text("id").primaryKey(),workspaceId:text("workspace_id").notNull(),repositoryUrl:text("repository_url").notNull(),ref:text("ref").notNull(),refPolicy:text("ref_policy").notNull(),skillPath:text("skill_path"),revision:integer("revision").notNull().default(1),archivedAt:utc("archived_at"),syncToken:text("sync_token"),syncExpiresAt:utc("sync_expires_at"),creationHash:text("creation_hash").notNull(),createdAt:utc("created_at").notNull().defaultNow(),updatedAt:utc("updated_at").notNull().defaultNow(),
},t=>[uniqueIndex("skill_sources_workspace_id_unique").on(t.workspaceId,t.id),index("skill_sources_workspace_idx").on(t.workspaceId,t.id),check("skill_sources_ref_policy_check",sql`${t.refPolicy} IN ('track','pin')`)]);
export const skillSourceRuns=pgTable("skill_source_runs",{
 id:text("id").primaryKey(),workspaceId:text("workspace_id").notNull(),sourceId:text("source_id").notNull(),sourceRevision:integer("source_revision").notNull(),commitSha:text("commit_sha").notNull(),plan:jsonb("plan").notNull(),results:jsonb("results").notNull().default([]),status:text("status").notNull().default("preview"),createdAt:utc("created_at").notNull().defaultNow(),appliedAt:utc("applied_at"),
},t=>[uniqueIndex("skill_source_runs_workspace_id_unique").on(t.workspaceId,t.id),foreignKey({columns:[t.workspaceId,t.sourceId],foreignColumns:[skillSources.workspaceId,skillSources.id]}),index("skill_source_runs_recent_idx").on(t.workspaceId,t.sourceId,t.createdAt),check("skill_source_runs_status_check",sql`${t.status} IN ('preview','partial','complete')`),check("skill_source_runs_commit_sha_check",sql`${t.commitSha} ~ '^[a-f0-9]{40}$'`)]);
export const skillSourceBindings=pgTable("skill_source_bindings",{
 workspaceId:text("workspace_id").notNull(),sourceId:text("source_id").notNull(),skillPath:text("skill_path").notNull(),skillId:text("skill_id").notNull(),lastCommitSha:text("last_commit_sha"),lastDigest:text("last_digest"),lastVersionId:text("last_version_id"),baseVersionId:text("base_version_id"),status:text("status").notNull().default("bound"),updatedAt:utc("updated_at").notNull().defaultNow(),
},t=>[primaryKey({columns:[t.sourceId,t.skillPath]}),uniqueIndex("skill_source_bindings_workspace_skill_unique").on(t.workspaceId,t.skillId),foreignKey({columns:[t.workspaceId,t.sourceId],foreignColumns:[skillSources.workspaceId,skillSources.id]}),foreignKey({columns:[t.workspaceId,t.skillId],foreignColumns:[skills.workspaceId,skills.id]})]);
export const skillVersionGitProvenance=pgTable("skill_version_git_provenance",{
 versionId:text("version_id").primaryKey(),workspaceId:text("workspace_id").notNull(),sourceId:text("source_id").notNull(),runId:text("run_id").notNull(),repositoryUrl:text("repository_url").notNull(),commitSha:text("commit_sha").notNull(),skillPath:text("skill_path").notNull(),bundleDigest:text("bundle_digest").notNull(),importedAt:utc("imported_at").notNull().defaultNow(),
},t=>[foreignKey({columns:[t.workspaceId,t.sourceId],foreignColumns:[skillSources.workspaceId,skillSources.id]}),foreignKey({columns:[t.workspaceId,t.runId],foreignColumns:[skillSourceRuns.workspaceId,skillSourceRuns.id]}),foreignKey({columns:[t.workspaceId,t.versionId],foreignColumns:[skillVersions.workspaceId,skillVersions.id]}),check("skill_version_git_provenance_commit_sha_check",sql`${t.commitSha} ~ '^[a-f0-9]{40}$'`)]);
export const gitSourceSchema={skill_sources:skillSources,skill_source_runs:skillSourceRuns,skill_source_bindings:skillSourceBindings,skill_version_git_provenance:skillVersionGitProvenance};
EOF
cat > packages/api/src/routes/git-sources.ts <<'EOF'
import { DomainError, GitSourceService } from "@skillplane/domain";
import type { Hono,Context } from "hono";
import type { ApiEnvironment } from "../context.js";
import { success } from "../envelopes.js";
import { workspaceUser,readJsonObject,requireIdempotencyKey,routingEpoch } from "./shared.js";
function service(c:Context<ApiEnvironment>) {const s=c.get("services");if(!s)throw new DomainError("AUTHENTICATION_REQUIRED","Authentication is required",401);return new GitSourceService(s.database.pool,s.skillService,s.skillVersionService);}
export function registerGitSourceRoutes(app:Hono<ApiEnvironment>) {
 const base="/api/v1/workspaces/:workspaceId/sources";
 const mutation=async(c:Context<ApiEnvironment>)=>({principal:await workspaceUser(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
 app.get(base,async c=>{const data=await service(c).list(await workspaceUser(c),c.req.query("cursor")??null);c.header("Cache-Control","private, no-store");return c.json(success(c,data));});
 app.post(base,async c=>{const m=await mutation(c),config=await readJsonObject(c);const source=await service(c).create({...m,config,idempotencyKey:requireIdempotencyKey(c)});return c.json(success(c,{source}),201);});
 app.get(`${base}/:sourceId`,async c=>{const data=await service(c).get(await workspaceUser(c),c.req.param("sourceId"));c.header("Cache-Control","private, no-store");return c.json(success(c,data));});
 app.patch(`${base}/:sourceId`,async c=>{const m=await mutation(c),body=await readJsonObject(c);if(typeof body.expectedRevision!=="number" || typeof body.archived!=="boolean")throw new DomainError("VALIDATION_FAILED","Revision and archived state are required",400);const source=await service(c).update({...m,sourceId:c.req.param("sourceId"),expectedRevision:body.expectedRevision,archived:body.archived,config:body});return c.json(success(c,{source}));});
 app.post(`${base}/:sourceId/bindings`,async c=>{const m=await mutation(c),body=await readJsonObject(c);if(typeof body.path!=="string" || typeof body.skillId!=="string")throw new DomainError("VALIDATION_FAILED","Path and skill ID are required",400);return c.json(success(c,await service(c).bind({...m,sourceId:c.req.param("sourceId"),path:body.path,skillId:body.skillId})));});
 app.post(`${base}/:sourceId/preview`,async c=>c.json(success(c,await service(c).preview({...await mutation(c),sourceId:c.req.param("sourceId")}))));
 app.post(`${base}/:sourceId/apply`,async c=>{const m=await mutation(c),body=await readJsonObject(c);if(typeof body.runId!=="string")throw new DomainError("VALIDATION_FAILED","Confirm a preview run ID",400);return c.json(success(c,await service(c).apply({...m,sourceId:c.req.param("sourceId"),runId:body.runId})));});
 app.get("/api/v1/workspaces/:workspaceId/skills/:skillId/versions/:versionId/source",async c=>{const p=await workspaceUser(c),s=c.get("services");if(!s)throw new DomainError("AUTHENTICATION_REQUIRED","Authentication is required",401);const version=await s.skillVersionService.get(c.req.param("versionId"),p);if(version.skillId!==c.req.param("skillId"))throw new DomainError("NOT_FOUND","Version was not found",404);c.header("Cache-Control","private, no-store");return c.json(success(c,{provenance:await service(c).provenance(p,version.id)}));});
}
EOF
