 {#if canManage&&!selected.source.archivedAt}<Button disabled={busy} onclick={()=>void run(previewSource)}>Preview sync</Button>{/if}
 <h3>Bound skills</h3><ul>{#each selected.bindings as binding(binding.path)}<li><a href={resolve("/(app)/[workspaceSlug]/skills/[skillSlug]",{workspaceSlug:workspace?.slug??"",skillSlug:binding.slug})}>{binding.name}</a> · <code>{binding.path||"/"}</code> · {binding.status}{#if binding.lastCommitSha}<a href={`${selected.source.repositoryUrl}/commit/${binding.lastCommitSha}`} target="_blank" rel="noreferrer">{binding.lastCommitSha.slice(0,12)}</a>{/if}</li>{/each}</ul>
 {#if canManage&&!selected.source.archivedAt}<details><summary>Bind an existing workspace skill</summary><p>Manual skills are linked only through this explicit action. Enter the skill ID from its detail view and the source directory.</p><form onsubmit={e=>{e.preventDefault();void run(bind);}}><Input label="Source path" bind:value={bindPath} /><Input label="Existing skill ID" bind:value={bindSkillId} required /><Button type="submit" disabled={busy}>Bind skill</Button></form></details>{/if}
 <h3>Recent syncs</h3><ul>{#each selected.runs as item(item.id)}<li>{item.createdAt} · {item.status} · <a href={`${selected.source.repositoryUrl}/commit/${item.commitSha}`} target="_blank" rel="noreferrer">{item.commitSha.slice(0,12)}</a><Button variant="ghost" disabled={busy} onclick={()=>preview=item}>View preview and results</Button></li>{/each}</ul>
 </section>{/if}
 {#if preview&&selected}<section aria-label="Sync preview"><h2>Sync preview</h2><p>Commit <a href={`${selected.source.repositoryUrl}/commit/${preview.commitSha}`} target="_blank" rel="noreferrer">{preview.commitSha}</a></p><p>New skills are private. Existing skill changes become candidates for review. Missing or renamed paths preserve existing skills.</p>
 <table><thead><tr><th>Path</th><th>Skill</th><th>Action</th><th>Details</th></tr></thead><tbody>{#each preview.plan as item(item.path)}<tr><td><code>{item.path||"/"}</code></td><td>{item.slug??"Invalid skill"}</td><td>{item.action}</td><td>{item.message??""}</td></tr>{/each}</tbody></table>
 {#if canManage&&!selected.source.archivedAt&&preview.status!=="complete"}<Button disabled={busy||!preview.plan.length} onclick={()=>void run(apply)}>{preview.status==="partial"?"Retry failed imports":"Apply this preview"}</Button>{/if}
 {#if preview.results.length}<h3>Sync results</h3><ul>{#each preview.results as result(result.path)}<li>{result.path||"/"} · {result.status} {result.message??""}</li>{/each}</ul>{/if}
