import { DomainError, GitSourceService } from "@skillplane/domain";
import type { Hono, Context } from "hono";
import type { ApiEnvironment } from "../context.js";
import { success } from "../envelopes.js";
import {
  workspaceUser,
  readJsonObject,
  requireIdempotencyKey,
  routingEpoch,
} from "./shared.js";
function service(c: Context<ApiEnvironment>) {
  const s = c.get("services");
  if (!s)
    throw new DomainError("AUTHENTICATION_REQUIRED", "Authentication is required", 401);
  return new GitSourceService(s.database.pool, s.skillService, s.skillVersionService);
}
export function registerGitSourceRoutes(app: Hono<ApiEnvironment>) {
  const base = "/api/v1/workspaces/:workspaceId/sources";
  const mutation = async (c: Context<ApiEnvironment>) => ({
    principal: await workspaceUser(c),
    requestId: c.get("requestId"),
    fencingEpoch: routingEpoch(c),
  });
  app.get(base, async (c) => {
    const data = await service(c).list(
      await workspaceUser(c),
      c.req.query("cursor") ?? null,
    );
    c.header("Cache-Control", "private, no-store");
    return c.json(success(c, data));
  });
  app.post(base, async (c) => {
    const m = await mutation(c),
      config = await readJsonObject(c);
    const source = await service(c).create({
      ...m,
      config,
      idempotencyKey: requireIdempotencyKey(c),
    });
    return c.json(success(c, { source }), 201);
  });
  app.get(`${base}/:sourceId`, async (c) => {
    const data = await service(c).get(await workspaceUser(c), c.req.param("sourceId"));
    c.header("Cache-Control", "private, no-store");
    return c.json(success(c, data));
  });
  app.patch(`${base}/:sourceId`, async (c) => {
    const m = await mutation(c),
      body = await readJsonObject(c);
    if (typeof body.expectedRevision !== "number" || typeof body.archived !== "boolean")
      throw new DomainError(
        "VALIDATION_FAILED",
        "Revision and archived state are required",
        400,
      );
    const source = await service(c).update({
      ...m,
      sourceId: c.req.param("sourceId"),
      expectedRevision: body.expectedRevision,
      archived: body.archived,
      config: body,
    });
    return c.json(success(c, { source }));
  });
  app.post(`${base}/:sourceId/bindings`, async (c) => {
    const m = await mutation(c),
      body = await readJsonObject(c);
    if (typeof body.path !== "string" || typeof body.skillId !== "string")
      throw new DomainError("VALIDATION_FAILED", "Path and skill ID are required", 400);
    return c.json(
      success(
        c,
        await service(c).bind({
          ...m,
          sourceId: c.req.param("sourceId"),
          path: body.path,
          skillId: body.skillId,
        }),
      ),
    );
  });
  app.delete(`${base}/:sourceId/bindings`, async (c) => {
    const m = await mutation(c),
      body = await readJsonObject(c);
    if (typeof body.path !== "string")
      throw new DomainError("VALIDATION_FAILED", "Binding path is required", 400);
    return c.json(
      success(
        c,
        await service(c).disconnect({
          ...m,
          sourceId: c.req.param("sourceId"),
          path: body.path,
        }),
      ),
    );
  });
  app.post(`${base}/:sourceId/preview`, async (c) =>
    c.json(
      success(
        c,
        await service(c).preview({
          ...(await mutation(c)),
          sourceId: c.req.param("sourceId"),
        }),
      ),
    ),
  );
  app.post(`${base}/:sourceId/apply`, async (c) => {
    const m = await mutation(c),
      body = await readJsonObject(c);
    if (typeof body.runId !== "string")
      throw new DomainError("VALIDATION_FAILED", "Confirm a preview run ID", 400);
    return c.json(
      success(
        c,
        await service(c).apply({
          ...m,
          sourceId: c.req.param("sourceId"),
          runId: body.runId,
        }),
      ),
    );
  });
  app.get(
    "/api/v1/workspaces/:workspaceId/skills/:skillId/versions/:versionId/source",
    async (c) => {
      const p = await workspaceUser(c),
        s = c.get("services");
      if (!s)
        throw new DomainError(
          "AUTHENTICATION_REQUIRED",
          "Authentication is required",
          401,
        );
      const version = await s.skillVersionService.get({
        skillId: c.req.param("skillId"),
        versionId: c.req.param("versionId"),
        principal: p,
        allowArchived: true,
      });
      if (version.skillId !== c.req.param("skillId"))
        throw new DomainError("NOT_FOUND", "Version was not found", 404);
      c.header("Cache-Control", "private, no-store");
      return c.json(
        success(c, { provenance: await service(c).provenance(p, version.id) }),
      );
    },
  );
}
import type { Pool, PoolClient } from "pg";
import { authorize } from "./authorization.js";
import { DomainError } from "./errors.js";
import type { Principal } from "./principal.js";
import { hashIdempotentRequest, validateIdempotencyKey } from "./idempotency.js";
import { withDomainTransaction } from "./transactions.js";
import { insertPrincipalAudit } from "./mutation-audit.js";
import type { SkillService } from "./skills.js";
import type { SkillVersionService } from "./skill-versions.js";
import {
  gitSourceConfig,
  PublicGitHubSourceProvider,
  type GitSourceConfig,
  type GitSourceProvider,
} from "./git-source-provider.js";
interface Mutation {
  principal: Principal;
  requestId: string;
  fencingEpoch?: number;
}
interface SourceRow {
  id: string;
  workspace_id: string;
  repository_url: string;
  ref: string;
  ref_policy: "track" | "pin";
  skill_path: string | null;
  revision: number;
  archived_at: Date | null;
  creation_hash: string;
  sync_token: string | null;
  sync_expires_at: Date | null;
  created_at: Date;
  updated_at: Date;
}
export interface GitSource {
  id: string;
  workspaceId: string;
  repositoryUrl: string;
  ref: string;
  refPolicy: "track" | "pin";
  path: string | null;
  revision: number;
  archivedAt: string | null;
  updatedAt: string;
}
function record(r: SourceRow): GitSource {
  return {
    id: r.id,
    workspaceId: r.workspace_id,
    repositoryUrl: r.repository_url,
    ref: r.ref,
    refPolicy: r.ref_policy,
    path: r.skill_path,
    revision: r.revision,
    archivedAt: r.archived_at?.toISOString() ?? null,
    updatedAt: r.updated_at.toISOString(),
  };
}
interface Binding {
  skill_path: string;
  skill_id: string;
  last_commit_sha: string | null;
  last_digest: string | null;
  last_version_id: string | null;
  base_version_id: string | null;
  status: string;
  current_published_version_id: string | null;
  archived_at: Date | null;
  slug: string;
  name: string;
  current_digest: string | null;
  disconnected_at: Date | null;
}
export interface GitPlanEntry {
  path: string;
  slug: string | null;
  digest: string | null;
  action: "added" | "changed" | "unchanged" | "missing" | "conflict" | "error";
  skillId: string | null;
  baseVersionId: string | null;
  bindingVersionId: string | null;
  message: string | null;
}
export interface GitApplyResult {
  path: string;
  status: string;
  skillId: string | null;
  versionId: string | null;
  message: string | null;
}
interface RunRow {
  id: string;
  workspace_id: string;
  source_id: string;
  source_revision: number;
  failure_message: string | null;
  commit_sha: string;
  plan: GitPlanEntry[];
  results: GitApplyResult[];
  status: "preview" | "partial" | "complete";
  created_at: Date;
  applied_at: Date | null;
}
function runRecord(r: RunRow) {
  return {
    id: r.id,
    commitSha: r.commit_sha,
    plan: r.plan,
    results: r.results,
    status: r.status,
    failureMessage: r.failure_message,
    createdAt: r.created_at.toISOString(),
    appliedAt: r.applied_at?.toISOString() ?? null,
  };
}
export class GitSourceService {
  constructor(
    private readonly pool: Pool,
    private readonly skills: SkillService,
    private readonly versions: SkillVersionService,
    private readonly provider: GitSourceProvider = new PublicGitHubSourceProvider(),
  ) {}
  private transaction<T>(m: Mutation, fn: (client: PoolClient) => Promise<T>) {
    return withDomainTransaction(this.pool, m.requestId, ({ client }) => fn(client), {
      fencingEpoch: m.fencingEpoch,
    });
  }
  private async audit(
    c: PoolClient,
    m: Mutation,
    id: string,
    event: string,
    metadata: Record<string, unknown> = {},
  ) {
    await insertPrincipalAudit(c, m.principal, {
      eventType: `skill_source.${event}`,
      action: "workspace:update",
      requestId: m.requestId,
      resourceType: "skill_source",
      resourceId: id,
      metadata,
    });
  }
  private async row(
    p: Principal,
    id: string,
    c: Pool | PoolClient = this.pool,
    lock = false,
  ) {
    authorize(p, "skills:read");
    const r = await c.query<SourceRow>(
      `SELECT * FROM skill_sources WHERE workspace_id=$1 AND id=$2 ${lock ? "FOR UPDATE" : ""}`,
      [p.workspaceId, id],
    );
    if (!r.rows[0]) throw new DomainError("NOT_FOUND", "Source was not found", 404);
    return r.rows[0];
  }
  async list(p: Principal, cursor: string | null = null) {
    authorize(p, "skills:read");
    if (cursor && cursor.length > 200)
      throw new DomainError("VALIDATION_FAILED", "Invalid source cursor", 400);
    const r = await this.pool.query<SourceRow>(
      "SELECT * FROM skill_sources WHERE workspace_id=$1 AND ($2::text IS NULL OR id>$2) ORDER BY id LIMIT 51",
      [p.workspaceId, cursor],
    );
    return {
      sources: r.rows.slice(0, 50).map(record),
      nextCursor: r.rows.length > 50 ? (r.rows[49]?.id ?? null) : null,
    };
  }
  async get(p: Principal, id: string) {
    const source = record(await this.row(p, id));
    const bindings = await this.bindings(p, id, true);
    const runs = await this.pool.query<RunRow>(
      "SELECT * FROM skill_source_runs WHERE workspace_id=$1 AND source_id=$2 ORDER BY created_at DESC,id DESC LIMIT 20",
      [p.workspaceId, id],
    );
    return {
      source,
      bindings: bindings.map((b) => ({
        path: b.skill_path,
        skillId: b.skill_id,
        slug: b.slug,
        name: b.name,
        status: b.status,
        disconnectedAt: b.disconnected_at?.toISOString() ?? null,
        lastCommitSha: b.last_commit_sha,
        lastDigest: b.last_digest,
        lastVersionId: b.last_version_id,
      })),
      runs: runs.rows.map(runRecord),
    };
  }
  async create(
    m: Mutation & { config: Record<string, unknown>; idempotencyKey: string },
  ) {
    authorize(m.principal, "workspace:update");
    const config = gitSourceConfig(m.config),
      key = validateIdempotencyKey(m.idempotencyKey),
      hash = await hashIdempotentRequest(config),
      id = `source:${await hashIdempotentRequest({ workspace: m.principal.workspaceId, actor: m.principal.actorId, key })}`;
    return this.transaction(m, async (c) => {
      const r = await c.query<SourceRow>(
        "INSERT INTO skill_sources(id,workspace_id,repository_url,ref,ref_policy,skill_path,creation_hash) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(id) DO UPDATE SET id=skill_sources.id RETURNING *",
        [
          id,
          m.principal.workspaceId,
          config.repositoryUrl,
          config.ref,
          config.refPolicy,
          config.path,
          hash,
        ],
      );
      const row = r.rows[0];
      if (!row) throw new DomainError("CONFLICT", "Source creation failed", 409);
      if (row.creation_hash !== hash)
        throw new DomainError(
          "IDEMPOTENCY_KEY_REUSED",
          "Creation key was already used",
          409,
        );
      // A creation audit has a deterministic resource ID; only emit once.
      const prior = await c.query(
        "SELECT 1 FROM audit_events WHERE workspace_id=$1 AND resource_id=$2 AND event_type='skill_source.created'",
        [m.principal.workspaceId, id],
      );
      if (!prior.rowCount) await this.audit(c, m, id, "created");
      return record(row);

