      source,
      bindings: bindings.map((b) => ({
        path: b.skill_path,
        skillId: b.skill_id,
        slug: b.slug,
        name: b.name,
        status: b.status,
        disconnectedAt: b.disconnected_at?.toISOString() ?? null,
        lastCommitSha: b.last_commit_sha,
